function validate(input) {
  const [{ Accounts = [] }] = input;
  const ids = new Set();
  for (const [id, income] of Accounts) {
    if (id === null) return 'Every account needs an account_id.';
    if (ids.has(id)) return `account_id ${id} appears twice in Accounts.`;
    ids.add(id);
    if (income === null || income < 0) return `Account ${id} needs a non-negative income.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  // Incomes right at the category edges, so < versus <= mistakes show up.
  const edges = [0, 19999, 20000, 50000, 50001];
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  // Small sets sometimes stay inside one or two categories so some counts are 0.
  const top = small ? [19999, 50000, 120000][Math.floor(rand() * 3)] : 120000;
  const Accounts = [];
  for (let i = 0; i < rows; i++) {
    const income = rand() < 0.25 ? edges[Math.floor(rand() * edges.length)] : Math.floor(rand() * (top + 1));
    Accounts.push([i + 1, Math.min(income, top)]);
  }
  // Shuffle the ids so they do not follow the row order.
  for (let i = Accounts.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Accounts[i][0], Accounts[j][0]] = [Accounts[j][0], Accounts[i][0]];
  }
  return [{ Accounts }];
}
